func Report(err error) {
	if err == nil {
		return
	}
	var sc StatusCoder
	if errors.As(err, &sc) {
		fmt.Fprintln(Out, sc.Error())
		exitFunc(sc.Status())
		return
	}
	if ge, ok := err.(GroupError); ok {
		exitFunc(reportGroup(ge))
		return
	}
}
