func reportGroup(ge GroupError) int {
	code := 1
	for _, e := range ge.Errors() {
		var sc StatusCoder
		if errors.As(e, &sc) {
			fmt.Fprintln(Out, sc.Error())
			code = sc.Status()
			continue
		}
		fmt.Fprintln(Out, e.Error())
	}
	return code
}
```
